% This file was generated by the Octave backend of RobCoGen, for model HyQ.


% TODO: possibly, in the future, optimize the spatial cross product (i.e.
%  avoid code that computes the whole 6x6 matrix)
function [tau a_trunk] = inverseDynamics(ip, xm, v_trunk, gravity, qd, qdd, fext)

if nargin < 7
    fext = cell(13,1);
    fext(:) = {zeros(6,1)};
end

%
% Pass 1. Forward propagate velocities and accelerations
%

% Link 'LF_hipassembly'
v_LF_hipassembly = xm.LF_hipassembly_X_trunk.mx * v_trunk;
v_LF_hipassembly(3) = v_LF_hipassembly(3) + qd(1);

vcross = vcross_mx(v_LF_hipassembly);

a_LF_hipassembly = vcross(:,3) * qd(1);
a_LF_hipassembly(3) = a_LF_hipassembly(3) + qdd(1);

f_LF_hipassembly = -fext{2} + ip.LF_hipassembly.tensor6D * a_LF_hipassembly + (-vcross' * ip.LF_hipassembly.tensor6D * v_LF_hipassembly);


% Link 'LF_upperleg'
v_LF_upperleg = xm.LF_upperleg_X_LF_hipassembly.mx * v_LF_hipassembly;
v_LF_upperleg(3) = v_LF_upperleg(3) + qd(2);

vcross = vcross_mx(v_LF_upperleg);

a_LF_upperleg = xm.LF_upperleg_X_LF_hipassembly.mx * a_LF_hipassembly + (vcross(:,3) * qd(2));
a_LF_upperleg(3) = a_LF_upperleg(3) + qdd(2);

f_LF_upperleg = -fext{3} + ip.LF_upperleg.tensor6D * a_LF_upperleg + (-vcross' * ip.LF_upperleg.tensor6D * v_LF_upperleg);


% Link 'LF_lowerleg'
v_LF_lowerleg = xm.LF_lowerleg_X_LF_upperleg.mx * v_LF_upperleg;
v_LF_lowerleg(3) = v_LF_lowerleg(3) + qd(3);

vcross = vcross_mx(v_LF_lowerleg);

a_LF_lowerleg = xm.LF_lowerleg_X_LF_upperleg.mx * a_LF_upperleg + (vcross(:,3) * qd(3));
a_LF_lowerleg(3) = a_LF_lowerleg(3) + qdd(3);

f_LF_lowerleg = -fext{4} + ip.LF_lowerleg.tensor6D * a_LF_lowerleg + (-vcross' * ip.LF_lowerleg.tensor6D * v_LF_lowerleg);


% Link 'RF_hipassembly'
v_RF_hipassembly = xm.RF_hipassembly_X_trunk.mx * v_trunk;
v_RF_hipassembly(3) = v_RF_hipassembly(3) + qd(4);

vcross = vcross_mx(v_RF_hipassembly);

a_RF_hipassembly = vcross(:,3) * qd(4);
a_RF_hipassembly(3) = a_RF_hipassembly(3) + qdd(4);

f_RF_hipassembly = -fext{5} + ip.RF_hipassembly.tensor6D * a_RF_hipassembly + (-vcross' * ip.RF_hipassembly.tensor6D * v_RF_hipassembly);


% Link 'RF_upperleg'
v_RF_upperleg = xm.RF_upperleg_X_RF_hipassembly.mx * v_RF_hipassembly;
v_RF_upperleg(3) = v_RF_upperleg(3) + qd(5);

vcross = vcross_mx(v_RF_upperleg);

a_RF_upperleg = xm.RF_upperleg_X_RF_hipassembly.mx * a_RF_hipassembly + (vcross(:,3) * qd(5));
a_RF_upperleg(3) = a_RF_upperleg(3) + qdd(5);

f_RF_upperleg = -fext{6} + ip.RF_upperleg.tensor6D * a_RF_upperleg + (-vcross' * ip.RF_upperleg.tensor6D * v_RF_upperleg);


% Link 'RF_lowerleg'
v_RF_lowerleg = xm.RF_lowerleg_X_RF_upperleg.mx * v_RF_upperleg;
v_RF_lowerleg(3) = v_RF_lowerleg(3) + qd(6);

vcross = vcross_mx(v_RF_lowerleg);

a_RF_lowerleg = xm.RF_lowerleg_X_RF_upperleg.mx * a_RF_upperleg + (vcross(:,3) * qd(6));
a_RF_lowerleg(3) = a_RF_lowerleg(3) + qdd(6);

f_RF_lowerleg = -fext{7} + ip.RF_lowerleg.tensor6D * a_RF_lowerleg + (-vcross' * ip.RF_lowerleg.tensor6D * v_RF_lowerleg);


% Link 'LH_hipassembly'
v_LH_hipassembly = xm.LH_hipassembly_X_trunk.mx * v_trunk;
v_LH_hipassembly(3) = v_LH_hipassembly(3) + qd(7);

vcross = vcross_mx(v_LH_hipassembly);

a_LH_hipassembly = vcross(:,3) * qd(7);
a_LH_hipassembly(3) = a_LH_hipassembly(3) + qdd(7);

f_LH_hipassembly = -fext{8} + ip.LH_hipassembly.tensor6D * a_LH_hipassembly + (-vcross' * ip.LH_hipassembly.tensor6D * v_LH_hipassembly);


% Link 'LH_upperleg'
v_LH_upperleg = xm.LH_upperleg_X_LH_hipassembly.mx * v_LH_hipassembly;
v_LH_upperleg(3) = v_LH_upperleg(3) + qd(8);

vcross = vcross_mx(v_LH_upperleg);

a_LH_upperleg = xm.LH_upperleg_X_LH_hipassembly.mx * a_LH_hipassembly + (vcross(:,3) * qd(8));
a_LH_upperleg(3) = a_LH_upperleg(3) + qdd(8);

f_LH_upperleg = -fext{9} + ip.LH_upperleg.tensor6D * a_LH_upperleg + (-vcross' * ip.LH_upperleg.tensor6D * v_LH_upperleg);


% Link 'LH_lowerleg'
v_LH_lowerleg = xm.LH_lowerleg_X_LH_upperleg.mx * v_LH_upperleg;
v_LH_lowerleg(3) = v_LH_lowerleg(3) + qd(9);

vcross = vcross_mx(v_LH_lowerleg);

a_LH_lowerleg = xm.LH_lowerleg_X_LH_upperleg.mx * a_LH_upperleg + (vcross(:,3) * qd(9));
a_LH_lowerleg(3) = a_LH_lowerleg(3) + qdd(9);

f_LH_lowerleg = -fext{10} + ip.LH_lowerleg.tensor6D * a_LH_lowerleg + (-vcross' * ip.LH_lowerleg.tensor6D * v_LH_lowerleg);


% Link 'RH_hipassembly'
v_RH_hipassembly = xm.RH_hipassembly_X_trunk.mx * v_trunk;
v_RH_hipassembly(3) = v_RH_hipassembly(3) + qd(10);

vcross = vcross_mx(v_RH_hipassembly);

a_RH_hipassembly = vcross(:,3) * qd(10);
a_RH_hipassembly(3) = a_RH_hipassembly(3) + qdd(10);

f_RH_hipassembly = -fext{11} + ip.RH_hipassembly.tensor6D * a_RH_hipassembly + (-vcross' * ip.RH_hipassembly.tensor6D * v_RH_hipassembly);


% Link 'RH_upperleg'
v_RH_upperleg = xm.RH_upperleg_X_RH_hipassembly.mx * v_RH_hipassembly;
v_RH_upperleg(3) = v_RH_upperleg(3) + qd(11);

vcross = vcross_mx(v_RH_upperleg);

a_RH_upperleg = xm.RH_upperleg_X_RH_hipassembly.mx * a_RH_hipassembly + (vcross(:,3) * qd(11));
a_RH_upperleg(3) = a_RH_upperleg(3) + qdd(11);

f_RH_upperleg = -fext{12} + ip.RH_upperleg.tensor6D * a_RH_upperleg + (-vcross' * ip.RH_upperleg.tensor6D * v_RH_upperleg);


% Link 'RH_lowerleg'
v_RH_lowerleg = xm.RH_lowerleg_X_RH_upperleg.mx * v_RH_upperleg;
v_RH_lowerleg(3) = v_RH_lowerleg(3) + qd(12);

vcross = vcross_mx(v_RH_lowerleg);

a_RH_lowerleg = xm.RH_lowerleg_X_RH_upperleg.mx * a_RH_upperleg + (vcross(:,3) * qd(12));
a_RH_lowerleg(3) = a_RH_lowerleg(3) + qdd(12);

f_RH_lowerleg = -fext{13} + ip.RH_lowerleg.tensor6D * a_RH_lowerleg + (-vcross' * ip.RH_lowerleg.tensor6D * v_RH_lowerleg);



%
% The force exerted on the floating base by the links
%
vcross = vcross_mx(v_trunk);
f_trunk = -fext{1} - vcross' * ip.trunk.tensor6D * v_trunk;

%
% Pass 2. Compute the composite inertia and the spatial forces
%
ci = rcg2.CompositeInertia(ip, xm);
ci.update_composite_inertia();
f_RH_upperleg = f_RH_upperleg + xm.RH_lowerleg_X_RH_upperleg.mx' * f_RH_lowerleg;
f_RH_hipassembly = f_RH_hipassembly + xm.RH_upperleg_X_RH_hipassembly.mx' * f_RH_upperleg;
f_trunk = f_trunk + xm.RH_hipassembly_X_trunk.mx' * f_RH_hipassembly;
f_LH_upperleg = f_LH_upperleg + xm.LH_lowerleg_X_LH_upperleg.mx' * f_LH_lowerleg;
f_LH_hipassembly = f_LH_hipassembly + xm.LH_upperleg_X_LH_hipassembly.mx' * f_LH_upperleg;
f_trunk = f_trunk + xm.LH_hipassembly_X_trunk.mx' * f_LH_hipassembly;
f_RF_upperleg = f_RF_upperleg + xm.RF_lowerleg_X_RF_upperleg.mx' * f_RF_lowerleg;
f_RF_hipassembly = f_RF_hipassembly + xm.RF_upperleg_X_RF_hipassembly.mx' * f_RF_upperleg;
f_trunk = f_trunk + xm.RF_hipassembly_X_trunk.mx' * f_RF_hipassembly;
f_LF_upperleg = f_LF_upperleg + xm.LF_lowerleg_X_LF_upperleg.mx' * f_LF_lowerleg;
f_LF_hipassembly = f_LF_hipassembly + xm.LF_upperleg_X_LF_hipassembly.mx' * f_LF_upperleg;
f_trunk = f_trunk + xm.LF_hipassembly_X_trunk.mx' * f_LF_hipassembly;

%
% The base acceleration due to the force due to the movement of the links
%
a_trunk = - ci.Ic_trunk \ f_trunk; % TODO optimise the inversion

%
% Pass 3. Compute the joint forces while propagating back the floating base acceleration
%
tau = zeros(size(qd));
a_LF_hipassembly = xm.LF_hipassembly_X_trunk.mx * a_trunk;
tau(1) = ci.Ic_LF_hipassembly(3,:) * a_LF_hipassembly + f_LF_hipassembly(3);

a_LF_upperleg = xm.LF_upperleg_X_LF_hipassembly.mx * a_LF_hipassembly;
tau(2) = ci.Ic_LF_upperleg(3,:) * a_LF_upperleg + f_LF_upperleg(3);

a_LF_lowerleg = xm.LF_lowerleg_X_LF_upperleg.mx * a_LF_upperleg;
tau(3) = ci.Ic_LF_lowerleg(3,:) * a_LF_lowerleg + f_LF_lowerleg(3);

a_RF_hipassembly = xm.RF_hipassembly_X_trunk.mx * a_trunk;
tau(4) = ci.Ic_RF_hipassembly(3,:) * a_RF_hipassembly + f_RF_hipassembly(3);

a_RF_upperleg = xm.RF_upperleg_X_RF_hipassembly.mx * a_RF_hipassembly;
tau(5) = ci.Ic_RF_upperleg(3,:) * a_RF_upperleg + f_RF_upperleg(3);

a_RF_lowerleg = xm.RF_lowerleg_X_RF_upperleg.mx * a_RF_upperleg;
tau(6) = ci.Ic_RF_lowerleg(3,:) * a_RF_lowerleg + f_RF_lowerleg(3);

a_LH_hipassembly = xm.LH_hipassembly_X_trunk.mx * a_trunk;
tau(7) = ci.Ic_LH_hipassembly(3,:) * a_LH_hipassembly + f_LH_hipassembly(3);

a_LH_upperleg = xm.LH_upperleg_X_LH_hipassembly.mx * a_LH_hipassembly;
tau(8) = ci.Ic_LH_upperleg(3,:) * a_LH_upperleg + f_LH_upperleg(3);

a_LH_lowerleg = xm.LH_lowerleg_X_LH_upperleg.mx * a_LH_upperleg;
tau(9) = ci.Ic_LH_lowerleg(3,:) * a_LH_lowerleg + f_LH_lowerleg(3);

a_RH_hipassembly = xm.RH_hipassembly_X_trunk.mx * a_trunk;
tau(10) = ci.Ic_RH_hipassembly(3,:) * a_RH_hipassembly + f_RH_hipassembly(3);

a_RH_upperleg = xm.RH_upperleg_X_RH_hipassembly.mx * a_RH_hipassembly;
tau(11) = ci.Ic_RH_upperleg(3,:) * a_RH_upperleg + f_RH_upperleg(3);

a_RH_lowerleg = xm.RH_lowerleg_X_RH_upperleg.mx * a_RH_upperleg;
tau(12) = ci.Ic_RH_lowerleg(3,:) * a_RH_lowerleg + f_RH_lowerleg(3);


a_trunk = a_trunk + gravity;

end

function vc = vcross_mx(v)
    vc = [   0    -v(3)  v(2)   0     0     0    ;
             v(3)  0    -v(1)   0     0     0    ;
            -v(2)  v(1)  0      0     0     0    ;
             0    -v(6)  v(5)   0    -v(3)  v(2) ;
             v(6)  0    -v(4)   v(3)  0    -v(1) ;
            -v(5)  v(4)  0     -v(2)  v(1)  0    ];
end
